 erc:{title:'Enfermedad renal crónica',symbol:'◈',subtitle:'Prioriza la protección renal y comprueba los ajustes del tratamiento en DM2.',version:'2026 · 1 página',fields:[['egfr','TFGe','number',1,180,'ml/min/1,73 m²'],['uacr','Cociente albúmina/creatinina','number',0,10000,'mg/g'],['chronic','Persistencia de la alteración','select',['yes:Confirmada durante al menos 3 meses','no:Menos de 3 meses o sin confirmar']],['k','Potasio','number',2,9,'mEq/l'],['meds','Tratamiento actual','meds']]},
