function quickAdvice(priority,control){
if(!quickFields[0][3].some(x=>x.split(':')[0]===priority)||!quickFields[1][3].some(x=>x.split(':')[0]===control))throw Error('Selecciona los dos criterios.');
const profiles={
none:{clinical:'Sin condicionante predominante: valorar metformina si se tolera y la función renal lo permite. Mantener alimentación, ejercicio, sueño y educación terapéutica.',drugs:['Metformina: base de la rama glucémica, si procede.','Otra clase no presente si falta control: elegir según perfil y tratamiento actual.']},
cv:{clinical:'Priorizar iSGLT2 y/o arGLP1 o agonista dual con evidencia cardiovascular, independientemente de HbA1c. Mantener metformina si procede.',drugs:['iSGLT2 con evidencia en reducción de eventos.','arGLP1 o agonista dual GIP-GLP1 con evidencia.','Metformina, si se tolera y la función renal lo permite.']},
ic:{clinical:'Priorizar iSGLT2 con beneficio en insuficiencia cardíaca, salvo contraindicación. Revisar además los pilares del tratamiento de IC según FEVI.',drugs:['iSGLT2 con beneficio demostrado en IC.','Metformina u otra clase para el control, si procede.'],caution:'En IC, revisar y evitar pioglitazona y saxagliptina. Confirmar TFGe y ficha técnica antes de iniciar iSGLT2.'},
erc:{clinical:'En DM2 y ERC, priorizar iSGLT2 si TFGe ≥20. Valorar semaglutida subcutánea según control y perfil; metformina solo si TFGe ≥30.',drugs:['iSGLT2: empagliflozina, dapagliflozina o canagliflozina, según ficha técnica.','Semaglutida subcutánea, según el perfil renal y glucémico.','Metformina, si TFGe ≥30; ajustar a función renal.'],caution:'Confirmar TFGe antes de elegir fármacos. Consulta la revisión opcional o el módulo renal.'},
obesity:{clinical:'Priorizar arGLP1 o agonista dual GIP-GLP1 y añadir o mantener metformina si procede. Personalizar alimentación y ejercicio; si IMC >35, considerar cirugía bariátrica.',drugs:['arGLP1 o agonista dual GIP-GLP1: valorar beneficio sobre peso.','Metformina, si procede.','iSGLT2 según el perfil cardiorrenal.']},
liver:{clinical:'El algoritmo contempla arGLP1 o agonista dual GIP-GLP1. Revisar fibrosis y causas secundarias en la ruta de enfermedad hepática metabólica.',drugs:['arGLP1 o agonista dual GIP-GLP1.','Pioglitazona o iSGLT2 según valoración individual.'],caution:'Pioglitazona requiere revisar contraindicaciones, especialmente IC; no elegir solo por el diagnóstico hepático.'},
fragile:{clinical:'Priorizar una pauta sencilla y evitar hipoglucemia. La rama de fragilidad contempla iDPP4 con metformina si procede; individualizar según situación funcional y esperanza de vida.',drugs:['iDPP4: opción de la rama de fragilidad.','Metformina, si se tolera y la función renal lo permite.'],caution:'En fragilidad moderada-grave, el PDF orienta a HbA1c 7,5–8,5%. Con vida limitada, priorizar confort y evitar síntomas.'}
};
const controls={
target:'No intensificar solo por HbA1c si está en el objetivo individual. Revisar tolerancia e hipoglucemias; la protección cardiorrenal puede justificar una clase aunque esté en objetivo. Control a los 6 meses.',
low:'Si sigue fuera del objetivo, comprobar adherencia y tolerancia y valorar añadir una clase no presente. Si persiste mal control con varias clases, considerar basal. Reevaluar a los 3 meses del cambio.',
high:'Si está asintomático y sin tratamiento, el algoritmo contempla doble terapia: metformina + otro antidiabético no insulínico si procede. Si ya está tratado, ajustar según lo que toma. Reevaluar a los 3 meses.',
sym:'Valorar insulina y metformina si la función renal lo permite. Investigar desencadenantes y gravedad clínica; una posible crisis hiperglucémica requiere atención urgente.',
unknown:'Acordar primero un objetivo individual según edad, evolución, fragilidad y complicaciones. La cifra de HbA1c aislada no determina una intensificación.'
};
const profile=profiles[priority];let drugs=[...profile.drugs];if(control==='sym')drugs=['Insulina: valorar insulinización tras evaluación clínica.','Metformina solo si procede y la función renal lo permite.'];
return {...profile,control:controls[control],drugs};
}
function updateQuick(){
const priority=$('priority').value,control=$('control').value;if(!priority||!control){$('results').innerHTML='<div class="quick-empty"><h3>Completa los dos criterios</h3><p>La orientación se actualiza al seleccionar las dos opciones.</p></div>';$('resultStatus').textContent='Falta un criterio';return;}
const advice=quickAdvice(priority,control);$('resultStatus').textContent='Orientación lista';$('resultStatus').className='status ready';
$('results').innerHTML=`<div class="quick-guidance"><section><h3>Manejo según condición clínica</h3><p>${escapeHtml(advice.clinical)}</p></section><section class="${control==='sym'?'urgent-text':''}"><h3>Manejo según control glucémico</h3><p>${escapeHtml(advice.control)}</p></section><section><h3>Clases de fármacos a valorar</h3><ul>${advice.drugs.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul></section>${advice.caution?`<p class="quick-caution">${escapeHtml(advice.caution)}</p>`:''}<p class="quick-note">Opciones de revisión, no para añadir todas. Sin dosis. Comprobar función renal, contraindicaciones y tratamiento actual.</p>${priority==='erc'||priority==='ic'?`<button type="button" class="ref" id="quickReference">Ver algoritmo de ${priority==='erc'?'ERC':'IC'}</button>`:''}</div>`;
if($('quickReference'))$('quickReference').onclick=()=>openPdf(priority);
}
